nta.declaration:
// Tower Defense Game - Vanilla Version
// Simplified for UPPAAL compatibility

// Game Constants
const int NUM_ENEMIES = 6;
const int TIMEOUT = 100;
const int LAST_SPAWN = 6;

// Enemy Parameters
const int CIRCLE_SPEED = 1;
const int CIRCLE_HEALTH = 10;
const int CIRCLE_DAMAGE = 2;
const int SQUARE_SPEED = 3;
const int SQUARE_HEALTH = 20;
const int SQUARE_DAMAGE = 4;

// Turret Parameters
const int BASIC_RANGE = 2;
const int BASIC_FIRE_SPEED = 2;
const int BASIC_DAMAGE = 2;
const int CANNON_RANGE = 1;
const int CANNON_FIRE_SPEED = 7;
const int CANNON_DAMAGE = 5;
const int SNIPER_RANGE = 4;
const int SNIPER_FIRE_SPEED = 20;
const int SNIPER_DAMAGE = 8;

// Main Tower
const int MAIN_TOWER_HEALTH = 10;

// Game State
int enemy_pos[NUM_ENEMIES] = {-1, -1, -1, -1, -1, -1};
int enemy_hp[NUM_ENEMIES] = {10, 10, 10, 20, 20, 20};
int enemy_damage[NUM_ENEMIES] = {2, 2, 2, 4, 4, 4};
int spawn_time[NUM_ENEMIES] = {0, 2, 4, 0, 3, 6};
int time_on_map[NUM_ENEMIES] = {0, 0, 0, 0, 0, 0};

int lives = MAIN_TOWER_HEALTH;
bool game_over = false;
int global_clock = 0;

// Path Length
const int PATH_LENGTH = 23;

// Turret positions (Configuration VI)
const int turret_x[7] = {5, 8, 8, 14, 14, 2, 11};
const int turret_y[7] = {5, 2, 6, 2, 6, 3, 5};
const int turret_type[7] = {0, 1, 1, 1, 1, 2, 2}; // 0=Basic, 1=Cannon, 2=Sniper
const int turret_range[7] = {2, 1, 1, 1, 1, 4, 4};
const int turret_damage[7] = {2, 5, 5, 5, 5, 8, 8};
const int turret_fire_speed[7] = {2, 7, 7, 7, 7, 20, 20};

// Simple helper functions
int abs_val(int x) {
    return x >= 0 ? x : -x;
}

int manhattan_dist(int x1, int y1, int x2, int y2) {
    return abs_val(x1-x2) + abs_val(y1-y2);
}

template.declaration:
clock move_clk;
int my_speed;
int my_damage;

clock fire_clk;
int my_range;
int my_damage;
int my_fire_speed;
int my_x;
int my_y;

nta.system:
// System composition
E0 = Enemy(0);
E1 = Enemy(1);
E2 = Enemy(2);
E3 = Enemy(3);
E4 = Enemy(4);
E5 = Enemy(5);

// Configuration VI turrets
//T0 = Turret(0); // Basic at (5,5)
//T1 = Turret(1); // Cannon at (8,2)
//T2 = Turret(2); // Cannon at (8,6)
//T3 = Turret(3); // Cannon at (14,2)
//T4 = Turret(4); // Cannon at (14,6)
//T5 = Turret(5); // Sniper at (2,3)
//T6 = Turret(6); // Sniper at (11,5)

GC = GameController();

system E0, E1, E2, E3, E4, E5, GC;
